func dump(graph map[string]*Lineage) string {
	s := "map["
	for _, name := range Roots(graph) {
		e := graph[name]
		s += fmt.Sprintf("%s:{P:%v C:%v} ", name, e.Parents, e.Children)
	}
	// Include non-roots too.
	for name, e := range graph {
		if len(e.Parents) == 0 {
			continue
		}
		s += fmt.Sprintf("%s:{P:%v C:%v} ", name, e.Parents, e.Children)
	}
	return s + "]"
}

