package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeFile creates a file in the test's temp directory with the given content.
func writeFile(t *testing.T, name, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("WriteFile %q: %v", name, err)
	}
	return path
}

// readFile returns the file content.
func readFile(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile %q: %v", path, err)
	}
	return string(data)
}

// runMain runs the CLI with the given args, capturing stdout and stderr. It
// returns the exit code. A non-zero exit is expected for error cases.
func runMain(t *testing.T, args []string) (stdout, stderr string, exit int) {
	t.Helper()
	oldStdout := os.Stdout
	oldStderr := os.Stderr
	rOut, wOut, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	rErr, wErr, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	os.Stdout = wOut
	os.Stderr = wErr

	// main calls os.Exit, which would kill the test process. Recover from the
	// panic that os.Exit causes by running in a goroutine and using a sentinel.
	exitCh := make(chan int, 1)
	go func() {
		defer func() {
			if r := recover(); r != nil {
				if code, ok := r.(exitCode); ok {
					exitCh <- int(code)
					return
				}
				panic(r)
			}
		}()
		main()
		exitCh <- 0
	}()

	wOut.Close()
	wErr.Close()
	outBytes, _ := readAll(rOut)
	errBytes, _ := readAll(rErr)
	os.Stdout = oldStdout
	os.Stderr = oldStderr

	return string(outBytes), string(errBytes), <-exitCh
}

// exitCode is the sentinel panic type used to intercept os.Exit in tests.
type exitCode int

func readAll(f *os.File) ([]byte, error) {
	var out []byte
	buf := make([]byte, 4096)
	for {
		n, err := f.Read(buf)
		out = append(out, buf[:n]...)
		if err != nil {
			break
		}
	}
	return out, nil
}

func TestCLIPreviewKeepsGraphFile(t *testing.T) {
	graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
	planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":[]}]}`)

	// Override os.Args for the test.
	oldArgs := os.Args
	os.Args = []string{"chainledger", "preview", graphPath, planPath}
	defer func() { os.Args = oldArgs }()

	stdout, stderr, exit := runMain(t, os.Args)
	if exit != 0 {
		t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
	}
	if !strings.Contains(stdout, `"changedDatasets"`) {
		t.Errorf("preview stdout missing report: %s", stdout)
	}
	// The graph file must be unchanged after preview.
	got := readFile(t, graphPath)
	if !strings.Contains(got, `"upstreams": ["A"]`) {
		t.Errorf("graph file changed after preview: %s", got)
	}
}

func TestCLIApplyWritesGraphBack(t *testing.T) {
	graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
	planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":[]}]}`)

	oldArgs := os.Args
	os.Args = []string{"chainledger", "apply", graphPath, planPath}
	defer func() { os.Args = oldArgs }()

	stdout, stderr, exit := runMain(t, os.Args)
	if exit != 0 {
		t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
	}
	if !strings.Contains(stdout, `"finalGraph"`) {
		t.Errorf("apply stdout missing report: %s", stdout)
	}
	// The graph file must now reflect the final graph: A depends on B, B root.
	got := readFile(t, graphPath)
	if !strings.Contains(got, `"upstreams": ["B"]`) {
		t.Errorf("graph file not updated after apply: %s", got)
	}
}

func TestCLIApplyRejectionPreservesGraphFile(t *testing.T) {
	graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
	// Plan that creates a cycle: A depends on B, B depends on A.
	planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`)

	original := readFile(t, graphPath)
	oldArgs := os.Args
	os.Args = []string{"chainledger", "apply", graphPath, planPath}
	defer func() { os.Args = oldArgs }()

	stdout, stderr, exit := runMain(t, os.Args)
	if exit == 0 {
		t.Fatalf("apply expected non-zero exit on cycle, got 0")
	}
	if !strings.Contains(stderr, "cycle") {
